// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockTime1, uint256 blockTime2) public {
        vm.assume(blockTime1 < blockTime2);
        vm.assume(blockTime1 > 0);
        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        vm.warp(blockTime1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        vm.warp(blockTime2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);
    }
}
